'use strict';
// Real geographic basemap. Risk overlays remain evidence status, never inferred safety.
V2NAV.splice(0,V2NAV.length,['dashboard','出行看板','route'],['map','地点风险','map'],['query','快捷查询','search'],['events','事件追踪与复盘','rain'],['feedback','用户反馈','message'],['community','互助与捐赠','message'],['about','关于与设置','layers']);
const v6FormBase=vForm;
vForm=function(){return v6FormBase().replace(/\slist="[^"]*"/g,'').replace(/<datalist\b[\s\S]*?<\/datalist>/g,'').replace('地点，或纬度,经度','输入小区、街道或详细地址').replace('选择途经地点','输入途经地点')};
const v6AboutBase=v5Base.about;
vAbout=function(){return v5Personal().replace('个人中心','个人中心与账号资料').replace('YOUR SPACE','ACCOUNT & PROFILE')+v6AboutBase()+v5End('关于与设置')};
let v6Map=null,v6View=null,v6Selected=null;
function v6DropMap(){if(v6Map){const c=v6Map.getCenter();v6View={lat:c.lat,lon:c.lng,zoom:v6Map.getZoom()};v6Map.remove();v6Map=null}}
function v6Risk(s){const p={origin:s.name,destination:s.name,vias:[]},events=vRelated(p);return events.some(e=>/暂停|封闭|停运/.test(e.category))?{color:'#ce5360',text:'历史公告涉及管制'}:vFeedback(p).length?{color:'#d38a36',text:'用户线索，待核验'}:vRisks(p).length?{color:'#4c76cb',text:'关联官方长期隐患'}:{color:'#829bc1',text:'当前风险未知'}}
vMapPage=function(){return vHead('PLACE & SURROUNDINGS','地点风险','在真实地图上查看地点与周边；地点标记表示资料状态。')+`<section class="card v6mapcard"><div class="row"><div><h2>深圳罗湖 · 地点地图</h2><small>拖动地图、缩放，点击地点标记或地图位置查看资料</small></div><button data-v6="overview">回到罗湖全图</button></div><div id="v6-geographic-map" aria-label="深圳罗湖交互地图"></div><div id="v6-map-status" class="v6mapstatus" role="status">正在加载地图底图…</div><div class="maplegend"><span><i class="key gray"></i>状态未知</span><span><i class="key" style="background:#4c76cb"></i>官方长期隐患关联</span><span><i class="key orange"></i>用户待核验线索</span><span><i class="key" style="background:#ce5360"></i>历史管制公告</span></div><form id="v5-place-form" class="queryform"><input name="place" value="${esc(V5.place)}" placeholder="输入地点名称，或纬度,经度"><button>查看地点</button></form><p class="muted">当前覆盖11个公开站点及已匹配资料；底图上的其他设施不自动拥有风险数据。输入小区名称可查询文字资料，完整地址定位仍待接入。</p><a href="https://www.openstreetmap.org/#map=14/22.555/114.135" target="_blank" rel="noopener">在OpenStreetMap打开此区域 ↗</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">报告底图问题 ↗</a>${v5Stamp('公开坐标收集2026-10-11；底图由地图服务动态提供')}</section><div id="v6-place-detail">${V5.place?v5PlaceDetail():'<section class="card"><h2>地点与周边详情</h2><p>在地图选点或输入地点名称即可查看资料。</p></section>'}</div>${v5End('地点风险')}`};
function v6MountMap(){const el=document.getElementById('v6-geographic-map');if(!el||V3.role!=='user'||V2.page!=='map')return;const status=document.getElementById('v6-map-status'),L=window.L;if(!L){if(status)status.textContent='地图组件未加载，请刷新页面；也可通过上方链接打开地图。';return}try{v6Map=L.map(el,{scrollWheelZoom:false,zoomControl:true});const selected=vResolve(V5.place);if(selected&&Number.isFinite(selected.lat)&&Number.isFinite(selected.lon)&&V5.place!==v6Selected){v6Map.setView([selected.lat,selected.lon],16);v6Selected=V5.place}else if(v6View)v6Map.setView([v6View.lat,v6View.lon],v6View.zoom);else v6Map.setView([22.555,114.135],13);let loaded=0;const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',updateWhenIdle:true});tiles.on('tileload',()=>{loaded++;if(status)status.textContent='地图可拖动、缩放；点位详情列出已收录公告、长期隐患与数据时间。'});tiles.on('tileerror',()=>{if(!loaded&&status)status.textContent='底图加载失败，可能受网络或地图服务影响；请刷新或打开地图链接。'});tiles.addTo(v6Map);D.stations.forEach(s=>{const r=v6Risk(s),marker=L.circleMarker([s.lat,s.lon],{bubblingMouseEvents:false,radius:8,color:'#fff',weight:2,fillColor:r.color,fillOpacity:1});marker.bindTooltip(esc(s.name)+' · '+r.text,{direction:'top'});marker.on('click',()=>{V5.place=s.name;vRender()});marker.addTo(v6Map)});if(selected&&Number.isFinite(selected.lat)&&Number.isFinite(selected.lon)){L.circle([selected.lat,selected.lon],{radius:1500,color:'#2457e8',weight:1,dashArray:'5 5',fillOpacity:.035}).addTo(v6Map);L.circleMarker([selected.lat,selected.lon],{radius:12,color:'#173854',weight:2,fillColor:'transparent',fillOpacity:0}).addTo(v6Map)}v6Map.on('click',e=>{V5.place=e.latlng.lat.toFixed(6)+','+e.latlng.lng.toFixed(6);vRender()});v6Map.invalidateSize()}catch{if(status)status.textContent='地图初始化失败，请刷新页面或打开地图链接。'}}
const v6RenderBase=vRender;
vRender=function(){v6DropMap();if(V2.page==='personal')V2.page='about';v6RenderBase();v6MountMap()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v6]');if(!b)return;if(b.dataset.v6==='overview'){v6DropMap();V5.place='';v6Selected=null;v6View=null;vRender()}});
vRender();
